                        # Check if colors[i] != colors[(i+1) % n]
                        if colors[i] != colors[(i + 1) % n]:
                            count += 1
                else:
                    # For size >= 3, check each starting position
                    for start in range(n):
                        is_alternating = True
                        # Check consecutive pairs in the group of size 'size'
                        for j in range(size - 1):
                            pos1 = (start + j) % n
                            pos2 = (start + j + 1) % n
                            if colors[pos1] == colors[pos2]:
                                is_alternating = False
                                break
                        if is_alternating:
                            count += 1

                result.append(count)

        return result
