    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def calculate_row_flips():
            flips = 0
            for i in range(m):
                for j in range(n // 2):
                    # Compare grid[i][j] with grid[i][n-1-j]
                    if grid[i][j] != grid[i][n - 1 - j]:
                        flips += 1
            return flips

        def calculate_col_flips():
            flips = 0
            for j in range(n):
                for i in range(m // 2):
                    # Compare grid[i][j] with grid[m-1-i][j]
                    if grid[i][j] != grid[m - 1 - i][j]:
                        flips += 1
            return flips

        # Return minimum flips needed to make either all rows or all columns palindromic
        return min(calculate_row_flips(), calculate_col_flips())

